<?php
require __DIR__.'/includes/db.php';
$slug=trim((string)($_GET['slug']??''));$story=null;$tracks=[];
if($slug!==''){$q=$pdo->prepare("SELECT * FROM stories WHERE slug=? AND status='published' AND story_type IN ('audio','both') LIMIT 1");$q->execute([$slug]);$story=$q->fetch();if($story){$q=$pdo->prepare("SELECT a.*,c.chapter_number,c.title AS chapter_title FROM audio_tracks a LEFT JOIN chapters c ON c.id=a.chapter_id WHERE a.story_id=? AND a.status='published' ORDER BY a.track_order,a.id");$q->execute([$story['id']]);$tracks=$q->fetchAll();}}
if(!$story){http_response_code(404);}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0910"><title><?= $story?e($story['title']).' – Truyện Audio | Truyện Đêm':'Không tìm thấy truyện audio'?></title><link rel="stylesheet" href="/css/style.css"><link rel="stylesheet" href="/css/site-matte-black.css"><link rel="stylesheet" href="/css/audio-post.css?v=20261120-1"></head><body class="story-site audio-post-page"><?php require __DIR__.'/includes/header.php';?><main class="audio-post-wrap"><?php if(!$story):?><section class="audio-post-empty"><h1>Không tìm thấy truyện audio</h1><a href="/blog.php">Quay lại thư viện</a></section><?php else:?><a class="audio-post-back" href="/blog.php">← Thư viện Truyện Đêm</a><article class="audio-post-hero"><?php if($story['cover_url']):?><img src="<?=e($story['cover_url'])?>" alt="<?=e($story['title'])?>"><?php endif;?><div class="audio-post-overlay"><span>☾ TRUYỆN AUDIO</span><h1><?=e($story['title'])?></h1><p><?=e($story['description']??'')?></p><small><?=e($story['author'])?> · <?=e($story['category'])?></small></div></article><section class="audio-post-playlist"><header><div><span>NGHE TRUYỆN</span><h2>Danh sách phát</h2></div><b><?=count($tracks)?> track</b></header><?php if(!$tracks):?><p class="audio-no-tracks">Audio đang được cập nhật. Hãy quay lại sau nhé.</p><?php else:?><div class="audio-post-track-list"><?php foreach($tracks as $i=>$t):?><article class="audio-post-track"><div class="audio-post-track-top"><span><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><div><h3><?=e($t['title'])?></h3><small><?=$t['chapter_id']?'Chương '.(int)$t['chapter_number'].' · '.e($t['chapter_title']):'Tập audio'?></small></div></div><audio controls preload="none" src="<?=e($t['audio_url'])?>">Trình duyệt không hỗ trợ audio.</audio></article><?php endforeach;?></div><?php endif;?></section><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?></body></html>